/// <reference types="../types/react-table-config" />

import { useVirtualizer, type Range } from '@tanstack/react-virtual';
import clsx from 'clsx';
import { isEqual } from 'lodash-es';
import React, { useCallback, useEffect, useMemo, useRef } from 'react';
import { FormattedMessage } from 'react-intl';
import { Column, TableInstance } from 'react-table';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { NoColumnsVisible, StyledBorder } from './DataTable.styles.js';
import { DataTableHeaderGroup } from './DataTableHeader.js';
import { DataTableVirtualizedContent } from './DataTableVirtualizedContent.js';
import { EmptyState } from './EmptyState.js';
import { LoadingState } from './LoadingState.js';
import { Text } from '../../typography/Text.js';
import { DataTableSlots } from '../hooks/useDataTableSlots.js';
import { useColumnsSizesActions } from '../plugins/use-column-sizes/actions.js';
import { useExpandableRowActions } from '../plugins/use-expandable-row/useExpandableRow.js';
import type { UserActionConfig } from '../plugins/use-user-actions/useUserActions.types.js';
import type { TableVariantConfig } from '../types/shared-table-types.js';
import {
  calculateVirtualHeight,
  getEstimatedWidth,
  getVirtualItemsRange,
  measureRowHeight,
} from '../utils/virtualization-utils.js';

export type DataTableContentProps = {
  instance: TableInstance<any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  slots: DataTableSlots;
  height?: number;
  lineWrap: boolean;
  userActions: UserActionConfig;
  tableVariant: TableVariantConfig;
  selectableRows: boolean;
  internalColumns: Column<any>[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  loading: boolean;
  columnVisibility: {
    [column: string]: 'hidden' | 'visible';
  };
  columnVirtualization: boolean;
};

export const DataTableContent = ({
  instance,
  slots,
  height,
  lineWrap,
  loading,
  userActions,
  tableVariant,
  internalColumns,
  columnVisibility,
  columnVirtualization,
}: DataTableContentProps) => {
  const {
    page,
    headerGroups,
    state: { expandedRows, columnGridTemplate },
    dispatch,
    prepareRow,
    getTableProps,
    getTableBodyProps,
    visibleColumns,
  } = instance;
  const virtualContainerRef = useRef<HTMLDivElement>(null);
  // Measuring final height of the table based on the required height.
  const tableHeight = calculateVirtualHeight(height, tableVariant.contained);

  const parentHeader = headerGroups.length > 1 ? headerGroups[0] : undefined;
  const childHeader = headerGroups[headerGroups.length - 1];
  const emptyColumns = internalColumns.length === 0;
  const emptyData = page.length === 0;
  const hasRatioWidth =
    instance?.allColumns.find((column) => column.ratioWidth !== undefined) !==
    undefined;

  // an array that accounts for all expanded rows and keeps track of how many rows are expanded before a certain index
  // whenever a number is increased by one from one index to the next an expandable row needs to be inserted
  const expandedRowOffsets = useMemo(
    () => {
      const offsets: number[] = [];
      let currentOffset = 0;
      for (const entry of page) {
        offsets.push(currentOffset);
        if (entry.isRowExpanded) {
          currentOffset++;
          offsets.push(currentOffset);
        }
      }
      return offsets;
    },

    // We need to know if any row's expand state changes happen and to do that we need `expandedRows` as a dependency.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [page, expandedRows],
  );

  // Notify the Table to cleanup expanded rows if slots.expandableRowTemplate has changed
  useEffect(() => {
    if (slots.expandableRowTemplate === null) {
      for (const rowId in expandedRows ?? {}) {
        dispatch({
          type: useExpandableRowActions.toggleRowExpanded,
          rowId: rowId,
          isExpanded: false,
        });
      }
    }
  }, [slots.expandableRowTemplate, expandedRows, dispatch]);

  // Virtualization
  const rowVirtualizer = useVirtualizer({
    count: expandedRowOffsets.length,
    getScrollElement: () => virtualContainerRef.current,
    estimateSize: useCallback(() => 37, []),
    measureElement: useCallback(
      (element: HTMLElement, entry: ResizeObserverEntry) =>
        measureRowHeight(element, entry, columnVirtualization),
      [columnVirtualization],
    ),
    overscan: 5,
  });

  // Column Virtualization
  const columnVirtualizer = useVirtualizer({
    count: columnVirtualization ? visibleColumns.length : 0,
    getScrollElement: () => virtualContainerRef.current,
    estimateSize: useCallback(
      (index) => getEstimatedWidth(visibleColumns[index]),
      [visibleColumns],
    ),
    horizontal: true,
    overscan: 5,
    rangeExtractor: useCallback(
      (range: Range) =>
        getVirtualItemsRange(range, !columnGridTemplate, childHeader),
      [childHeader, columnGridTemplate],
    ),
  });

  const virtualColumns = columnVirtualizer.getVirtualItems();
  const virtualColumnIndices = useMemo(
    () => virtualColumns.map((column) => column.index),
    [virtualColumns],
  );
  const prevIndices = useRef(virtualColumnIndices);

  // notify the columnSizes plugin once the rendered columns changed to remeasure autoWidths if necessary
  if (
    columnVirtualization &&
    !isEqual(prevIndices.current, virtualColumnIndices)
  ) {
    if (prevIndices.current.length !== 0) {
      Promise.resolve().then(() => {
        dispatch({
          type: useColumnsSizesActions.visibleColumnsChanged,
        });
      });
    }
    prevIndices.current = virtualColumnIndices;
  }

  if (headerGroups.length === 0 && !loading) {
    return (
      <NoColumnsVisible>
        <Text textStyle="base" as="p">
          <FormattedMessage
            defaultMessage="No table columns visible."
            id="0hFQ7cTaFNP7qUY3"
            description="When all columns are hidden, this is shown in the main table area."
          />
        </Text>
      </NoColumnsVisible>
    );
  }

  return (
    <StyledBorder
      className={clsx({
        'strato-table-contained': tableVariant.contained,
      })}
      {...getTableProps()}
    >
      <div
        ref={virtualContainerRef}
        className="strato-table-virtualization-container"
        style={{
          height: tableHeight,
        }}
      >
        {!emptyColumns && (
          <div
            role="rowgroup"
            draggable="false"
            className={clsx('strato-table-header-group', {
              'strato-table-header-has-parent': !!parentHeader,
            })}
          >
            <DataTableHeaderGroup
              dispatch={dispatch}
              userActions={userActions}
              parentHeaderGroup={parentHeader}
              childHeaderGroup={childHeader}
              columnVisibility={columnVisibility}
              hasRatioWidth={hasRatioWidth}
              tableContainerRef={virtualContainerRef}
              columnVirtualizer={columnVirtualizer}
              columnVirtualization={columnVirtualization}
              isGridLayout={!!columnGridTemplate}
            ></DataTableHeaderGroup>
          </div>
        )}
        <div
          className="strato-loading-wrapper"
          style={{
            minHeight:
              emptyData && emptyColumns
                ? `calc(${Spacings.Size64} + ${Spacings.Size40})`
                : Spacings.Size36,
          }}
        >
          {!emptyData ? (
            <div
              {...getTableBodyProps()}
              style={{
                height: rowVirtualizer.getTotalSize(),
                position: 'relative',
                ...(columnVirtualization && {
                  width: columnVirtualizer.getTotalSize() - 1,
                  overflow: 'hidden',
                }),
              }}
            >
              <DataTableVirtualizedContent
                dispatch={dispatch}
                page={page}
                expandedRowOffsets={expandedRowOffsets}
                rowVirtualizer={rowVirtualizer}
                columnVirtualizer={columnVirtualizer}
                columnVirtualization={columnVirtualization}
                prepareRow={prepareRow}
                expandableRowTemplate={slots.expandableRowTemplate}
                lineWrap={lineWrap}
                tableVariant={tableVariant}
                userActions={userActions}
                tableContainerRef={virtualContainerRef}
                isGridLayout={!!columnGridTemplate}
              />
            </div>
          ) : slots.emptyState && !loading ? (
            slots.emptyState
          ) : (
            !loading && <EmptyState />
          )}
          {loading && (
            <LoadingState
              loaderBackground={
                !tableVariant.contained ? 'transparent' : undefined
              }
              leftOffset={virtualContainerRef.current?.scrollLeft}
            />
          )}
        </div>
      </div>
    </StyledBorder>
  );
};
